nextflow_process {

    name "Test Process GLIMPSE2_PHASE"
    script "../main.nf"
    config "./nextflow.config"

    process "GLIMPSE2_PHASE"

    tag "modules_nfcore"
    tag "modules"
    tag "glimpse2"
    tag "glimpse2/phase"
    tag "samtools/view"
    tag "samtools"

    test("homo_sapiens - vcf region - panel") {
        when {
            process {
                """
                input_vcf = channel.of([
                    [ id:'input' ],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz", checkIfExists: true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz.csi", checkIfExists: true),
                    [], [],
                    "chr22:16600000-16800000",
                    "chr22:16650000-16750000"
                ])

                ref_panel = channel.of([
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz", checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz.csi", checkIfExists:true),
                ])

                map_file = channel.of([[]])

                // [meta, vcf, index, sample_infos, regionin, regionout,ref, index, map] [meta, fasta, fai]
                input[0] = input_vcf
                    .combine(ref_panel)
                    .combine(map_file)
                input[1] = channel.of([[],[],[]])
                input[2] = []
                """
            }
        }

        then {
            assert process.success
            assert snapshot(
                process.out.phased_variants.collect { meta, vcf -> [
                        meta,
                        file(vcf).name,
                        path(vcf).vcf.summary,
                        path(vcf).vcf.variantsMD5
                ] },
                process.out.stats_coverage,
                process.out.findAll { key, val -> key.startsWith('versions') }
            ).match()
        }

    }

    test("homo_sapiens - bam region - panel") {
        when {
            process {
                """
                input_bam = channel.of([
                    [id:'input'],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/NA12878.chr21_22.1X.bam", checkIfExists: true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/NA12878.chr21_22.1X.bam.bai", checkIfExists: true),
                    [], [],
                    "chr22:16600000-16800000",
                    "chr22:16650000-16750000",
                ])

                ref_panel = channel.of([
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz", checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz.csi", checkIfExists:true),
                ])

                map_file = channel.of([[]])

                // [meta, vcf, index, sample_infos, regionin, regionout,ref, index, map] [meta, fasta, fai]
                input[0] = input_bam
                    .combine(ref_panel)
                    .combine(map_file)
                input[1] = channel.of([[],[],[]])
                input[2] = []
                """
            }
        }

        then {
            assert process.success
            assert snapshot(
                process.out.phased_variants.collect { meta, vcf -> [
                        meta,
                        file(vcf).name,
                        path(vcf).vcf.summary,
                        path(vcf).vcf.variantsMD5
                ] },
                process.out.stats_coverage,
                process.out.findAll { key, val -> key.startsWith('versions') }
            ).match()
        }

    }

    test("homo_sapiens - cram region - panel - fasta") {
        setup {
            run ("SAMTOOLS_VIEW") {
                script "../../../samtools/view"
                process {
                    """
                    input[0] = channel.of([
                        [id:'input'],
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/NA12878.chr21_22.1X.bam", checkIfExists: true),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/NA12878.chr21_22.1X.bam.bai", checkIfExists: true)
                    ])
                    input[1] = channel.of([
                        [id: 'Hg38'],
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/genome/genomeGRCh38_chr21_22.fa.gz", checkIfExists: true),
                        []
                    ])
                    input[2] = [[], []]
                    input[3] = [[], []]
                    input[4] = "crai"
                    """
                }
            }
        }

        when {
            process {
                """
                input_cram = SAMTOOLS_VIEW.out.cram
                    .join(SAMTOOLS_VIEW.out.crai)
                    .combine(channel.of([
                        [], [],
                        "chr22:16600000-16800000",
                        "chr22:16650000-16750000",
                    ]))
                ref_panel = channel.of([
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz", checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz.csi", checkIfExists:true)
                ])

                map_file = channel.of([[]])

                reference_genome = channel.of([
                    [id: 'Hg38'],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/genome/genomeGRCh38_chr21_22.fa.gz", checkIfExists: true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/genome/genomeGRCh38_chr21_22.fa.gz.fai", checkIfExists: true)
                ])

                // [meta, vcf, index, sample_infos, regionin, regionout,ref, index, map] [meta, fasta, fai]
                input[0] = input_cram
                    .combine(ref_panel)
                    .combine(map_file)
                input[1] = reference_genome
                input[2] = []
                """
                }
        }

        then {
            assert process.success
            assert snapshot(
                process.out.phased_variants.collect { meta, vcf -> [
                        meta,
                        file(vcf).name,
                        path(vcf).vcf.summary,
                        path(vcf).vcf.variantsMD5
                ] },
                process.out.stats_coverage,
                process.out.findAll { key, val -> key.startsWith('versions') }
            ).match()
        }
    }

    test("homo_sapiens - [bam, bam] region - panel") {
        when {
            process {
                """
                input_bam = channel.of([
                    [id:'input'],
                    [
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/NA12878.chr21_22.1X.bam", checkIfExists: true),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/NA19401.chr21_22.1X.bam", checkIfExists: true)
                    ],
                    [
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/NA12878.chr21_22.1X.bam.bai", checkIfExists: true),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/NA19401.chr21_22.1X.bam.bai", checkIfExists: true)
                    ],
                    [], [],
                    "chr22:16600000-16800000",
                    "chr22:16650000-16750000",
                ])
                ref_panel = channel.of([
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz", checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz.csi", checkIfExists:true)
                ])

                map_file = channel.of([[]])

                // [meta, vcf, index, sample_infos, regionin, regionout,ref, index, map] [meta, fasta, fai]
                input[0] = input_bam
                    .combine(ref_panel)
                    .combine(map_file)
                input[1] = channel.of([[],[],[]])
                input[2] = []
                """
                }
        }

        then {
            assert process.success
            assert snapshot(
                process.out.phased_variants.collect { meta, vcf -> [
                        meta,
                        file(vcf).name,
                        path(vcf).vcf.summary,
                        path(vcf).vcf.variantsMD5
                ] },
                process.out.stats_coverage,
                process.out.findAll { key, val -> key.startsWith('versions') }
            ).match()
        }
    }

    test("Error file type inconsistent") {
        when {
            process {
                """
                input_bam = channel.of([
                    [id:'input'],
                    [
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/NA12878.chr21_22.1X.bam", checkIfExists: true),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz", checkIfExists: true)
                    ],
                    [
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/NA12878.chr21_22.1X.bam.bai", checkIfExists: true),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz.csi", checkIfExists: true)
                    ],
                    [], [],
                    "chr22:16600000-16800000",
                    "chr22:16650000-16750000",
                    [], [], []
                ])

                // [meta, vcf, index, sample_infos, regionin, regionout,ref, index, map] [meta, fasta, fai]
                input[0] = input_bam
                input[1] = channel.of([[],[],[]])
                input[2] = []
                """
                }
        }

        then {
            assert process.failed
            assert process.errorReport.contains("Input files must be of the same type and either .bam/.cram or .vcf/.vcf.gz/.bcf format. Found: [bam, gl]")
        }
    }

    test("Error only one vcf allowed") {
        when {
            process {
                """
                input_bam = channel.of([
                    [id:'input'],
                    [
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA19401.chr21_22.1X.glimpse2.vcf.gz", checkIfExists: true),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz", checkIfExists: true),
                    ],
                    [
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA19401.chr21_22.1X.glimpse2.vcf.gz.csi", checkIfExists: true),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz.csi", checkIfExists: true),
                    ],
                    [], [],
                    "chr21:16600000-16800000",
                    "chr21:16650000-16750000",
                    [], [], []
                ])

                // [meta, vcf, index, sample_infos, regionin, regionout,ref, index, map] [meta, fasta, fai]
                input[0] = input_bam
                input[1] = channel.of([[],[],[]])
                input[2] = []
                """
                }
        }

        then {
            assert process.failed
            assert process.errorReport.contains("Only one input .vcf/.vcf.gz/.bcf file can be provided")
        }
    }

    test("homo_sapiens - [bam, bam] region sample rename - panel") {
        when {
            process {
                """
                bamlist = channel.of(
                    "NA12878.chr21_22.1X.bam\tSample1",
                    "NA19401.chr21_22.1X.bam\tSample2"
                ).collectFile(name: 'bamlist.txt', newLine: true)

                input_bam = channel.of([
                    [id:'input'],
                    [
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/NA12878.chr21_22.1X.bam", checkIfExists: true),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/NA19401.chr21_22.1X.bam", checkIfExists: true)
                    ],
                    [
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/NA12878.chr21_22.1X.bam.bai", checkIfExists: true),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/NA19401.chr21_22.1X.bam.bai", checkIfExists: true)
                    ],
                ]).combine(bamlist)
                .map{ map, bam, bai, sample_list -> [
                    map, bam, bai, sample_list, [],
                    "chr22:16600000-16800000",
                    "chr22:16650000-16750000",
                ]}

                ref_panel = channel.of([
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz", checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz.csi", checkIfExists:true)
                ])

                map_file = channel.of([[]])
                // [meta, vcf, index, sample_infos, regionin, regionout,ref, index, map] [meta, fasta, fai]
                input[0] = input_bam
                    .combine(ref_panel)
                    .combine(map_file)
                input[1] = channel.of([[],[],[]])
                input[2] = []
                """
                }
        }

        then {
            assert process.success
            assert snapshot(
                process.out.phased_variants.collect { meta, vcf -> [
                        meta,
                        file(vcf).name,
                        path(vcf).vcf.summary,
                        path(vcf).vcf.variantsMD5
                ] },
                process.out.stats_coverage,
                process.out.findAll { key, val -> key.startsWith('versions') }
            ).match()
        }
    }

    test("homo_sapiens - vcf region - panel - bcf output -- stub") {
        options "-stub"
        when {
            process {
                """
                input_vcf = channel.of([
                    [ id:'input' ],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz", checkIfExists: true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz.csi", checkIfExists: true),
                    [], [],
                    "chr22:16600000-16800000",
                    "chr22:16650000-16750000",
                    [], [], []
                ])

                // [meta, vcf, index, sample_infos, regionin, regionout,ref, index, map] [meta, fasta, fai]
                input[0] = input_vcf
                input[1] = channel.of([[],[],[]])
                input[2] = "bcf"
                """
            }
        }

        then {
            assert process.success
            assert snapshot(sanitizeOutput(process.out)).match()
        }

    }
}

